def compute(vars):
    total = vars["v2"]
    after_2020 = vars["v1"]

    if total == 0:
        return None

    ratio = after_2020 / total
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "after_2020": after_2020,
            "total": total,
            "ratio": ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
